def solve(grid):
    """
    The transformation consists of discovering the smallest vertical period p and
    horizontal period q such that the grid is a repetition of a p×q tile.
    All cells equal to 0 are missing; they must be replaced by the value that
    belongs to the corresponding position in the tile.
    The tile is built from the non‑zero cells of the input; any still unknown
    position is filled with the first known value in its row or column (if any).
    Finally the complete tile is repeated to obtain the output grid.
    """
    if not grid:
        return grid

    n = len(grid)
    m = len(grid[0])

    # ---------- find vertical period ----------
    p = 1
    while p < n:
        ok = True
        for i in range(n - p):
            for j in range(m):
                if grid[i][j] != 0 and grid[i + p][j] != 0 and grid[i][j] != grid[i + p][j]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            break
        p += 1

    # ---------- find horizontal period ----------
    q = 1
    while q < m:
        ok = True
        for i in range(n):
            for j in range(m - q):
                if grid[i][j] != 0 and grid[i][j + q] != 0 and grid[i][j] != grid[i][j + q]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            break
        q += 1

    # ----- build the tile (p rows, q columns) -----
    tile = [[0] * q for _ in range(p)]

    # known values
    for i in range(n):
        for j in range(m):
            if grid[i][j] != 0:
                r = i % p
                c = j % q
                if tile[r][c] == 0:
                    tile[r][c] = grid[i][j]
                # consistency check (the problem guarantees consistency)
                # else:
                #    assert tile[r][c] == grid[i][j]

    # fill any still unknown cells using the first known value in the same
    # row or column of the tile (if such a value exists)
    for r in range(p):
        for c in range(q):
            if tile[r][c] == 0:
                # try row r
                for cc in range(q):
                    if tile[r][cc] != 0:
                        tile[r][c] = tile[r][cc]
                        break
                # if still unknown, try column c
                if tile[r][c] == 0:
                    for rr in range(p):
                        if tile[rr][c] != 0:
                            tile[r][c] = tile[rr][c]
                            break
                # as a last resort keep 0 (should not happen for the given data)
    # ----- reconstruct the whole grid -----
    out = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            out[i][j] = tile[i % p][j % q]

    return out

